#include "capsule.hpp"
#include <cstring>
int main(){try {auto a=hipRollModel(),b=capsuleModel();auto&x=a.mechanics;auto&y=b.mechanics;need(x.bodyNames==y.bodyNames&&x.jointNames==y.jointNames&&x.shapeNames==y.shapeNames&&x.defaultQ==y.defaultQ&&x.defaultV==y.defaultV,"topology changed");need(x.collisionExclusions.size()==y.collisionExclusions.size(),"exclusions changed");for(unsigned i=0;i<x.collisionExclusions.size();i++)need(x.collisionExclusions[i].colliderA==y.collisionExclusions[i].colliderA&&x.collisionExclusions[i].colliderB==y.collisionExclusions[i].colliderB,"exclusion changed");for(unsigned i=0;i<x.bodies.size();i++)need(!std::memcmp(&x.bodies[i],&y.bodies[i],sizeof(x.bodies[i])),"body changed");for(unsigned i=0;i<x.joints.size();i++)need(!std::memcmp(&x.joints[i],&y.joints[i],sizeof(x.joints[i])),"joint changed");for(unsigned i=0;i<x.dofs.size();i++)need(!std::memcmp(&x.dofs[i],&y.dofs[i],sizeof(x.dofs[i])),"dof changed");unsigned changed=0;for(unsigned i=0;i<x.shapes.size();i++){auto&old=x.shapes[i];auto&now=y.shapes[i];bool rear=x.shapeNames[i].find("rear_toe_")!=std::string::npos;if(rear){changed++;need(old.shapeType==MR_SHAPE_BOX && now.shapeType==MR_SHAPE_CAPSULE,"type");need(std::abs(now.dimensions.x+now.dimensions.y-old.dimensions.x)<1e-7,"extent");need(std::abs(now.localPosition.z-now.dimensions.x+old.dimensions.z)<1e-7,"neutral bottom");auto z=now;z.shapeType=old.shapeType;z.localPosition=old.localPosition;z.localRotation=old.localRotation;z.dimensions=old.dimensions;z.contactRestAndBoundingRadius.z=old.contactRestAndBoundingRadius.z;need(!std::memcmp(&z,&old,sizeof(z)),"unexpected shape field");}else need(!std::memcmp(&old,&now,sizeof(old)),"other shape changed");}need(changed==4&&y.defaultV.size()==40,"wrong shape count");std::cout<<"changed_shapes "<<changed<<" bodies "<<y.bodies.size()<<" joints "<<y.joints.size()<<" dofs "<<y.defaultV.size()<<" unchanged_exclusions "<<y.collisionExclusions.size()<<" neutral_extent_and_bottom_preserved 1\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
